pub struct FileCache { inner: Mutex<Inner> }   // or RwLock<Inner>, or parking_lot::Mutex<Inner>

impl FileCache {
    pub fn find(&self, path: &str) -> Option<String> {
        let guard = self.inner.lock().expect("poisoned"); // the guard IS the scoped lock
        guard.find_locked(path)                           // released on drop
    }
}

